// Extract domain from ig_website for Hunter.io lookup
const record = $input.item.json;
const fields = record.fields || {};
const website = fields.ig_website || '';

let domain = '';
try {
  if (website) {
    const url = website.startsWith('http') ? website : 'https://' + website;
    domain = new URL(url).hostname.replace('www.', '');
  }
} catch(e) {
  domain = '';
}

return [{
  json: {
    record_id: record.id,
    ig_handle: fields.ig_handle || '',
    ig_website: website,
    ig_bio: fields.ig_bio || '',
    ig_followers: fields.ig_followers || 0,
    domain: domain,
    source_detail: fields.source_detail || ''
  }
}];

// Extract first email from Hunter.io response
const hunterData = $input.item.json;
const emails = hunterData?.data?.emails || [];

let email = '';
let email_confidence = 0;
let email_found = false;

if (emails.length > 0) {
  // Pick highest confidence email
  const sorted = emails.sort((a, b) => (b.confidence || 0) - (a.confidence || 0));
  email = sorted[0].value || '';
  email_confidence = sorted[0].confidence || 0;
  email_found = email.length > 0;
}

return [{
  json: {
    email,
    email_confidence,
    email_found
  }
}];

// Parse Apify profile scraper output
const items = $input.item.json;
const profile = Array.isArray(items) ? items[0] : items;

if (!profile) {
  return [{ json: {
    follower_count: 0,
    following_count: 0,
    posts_count: 0,
    is_business_account: false,
    bio_links: [],
    story_highlights: [],
    recent_posts_sample: '',
    recent_posts_avg_likes: 0,
    is_verified: false
  }}];
}

// Extract recent post captions (last 3)
const posts = profile.latestPosts || profile.posts || [];
const recentCaptions = posts.slice(0, 3).map(p => p.caption || '').filter(Boolean);
const recentPostsSample = recentCaptions.join(' | ');

// Average likes
const avgLikes = posts.length > 0
  ? Math.round(posts.slice(0, 9).reduce((sum, p) => sum + (p.likesCount || 0), 0) / Math.min(posts.length, 9))
  : 0;

// Bio links
const bioLinks = [];
if (profile.externalUrl) bioLinks.push(profile.externalUrl);
if (profile.bioLinks) bioLinks.push(...profile.bioLinks.map(l => l.url || l));

// Story highlights
const highlights = (profile.highlightReels || []).map(h => h.title || h.name || '');

return [{
  json: {
    follower_count: profile.followersCount || 0,
    following_count: profile.followingCount || 0,
    posts_count: profile.postsCount || 0,
    is_business_account: profile.isBusinessAccount || false,
    bio_links: bioLinks,
    story_highlights: highlights,
    recent_posts_sample: recentPostsSample.substring(0, 1000),
    recent_posts_avg_likes: avgLikes,
    is_verified: profile.verified || false
  }
}];

// Check bio links for product page signals
const profileData = $('Parse Profile Data').item.json;
const bioLinks = profileData.bio_links || [];

const productSignals = ['stan.store', 'exly.app', 'graphy.com', 'kajabi.com', 'razorpay.com', 'instamojo', 'gumroad', 'patreon'];
const bookingSignals = ['calendly.com', 'topmate.io', 'cal.com', 'tidycal'];

const allLinksText = bioLinks.join(' ').toLowerCase();

const has_product_page = productSignals.some(signal => allLinksText.includes(signal));
const has_booking = bookingSignals.some(signal => allLinksText.includes(signal));

return [{
  json: {
    has_product_page,
    has_booking,
    bio_links_str: bioLinks.join(', ')
  }
}];

// Merge all enrichment data
const recordData = $('Extract Domain').item.json;
const emailData = $('Extract Email').item.json;
const profileData = $('Parse Profile Data').item.json;
const bioClassification = $('Classify Bio Links').item.json;

return [{
  json: {
    record_id: recordData.record_id,
    ig_handle: recordData.ig_handle,
    // Email data
    email: emailData.email || '',
    email_confidence: emailData.email_confidence || 0,
    email_found: emailData.email_found || false,
    // Profile data
    ig_followers: profileData.follower_count || recordData.ig_followers || 0,
    ig_following: profileData.following_count || 0,
    ig_posts_count: profileData.posts_count || 0,
    is_business_account: profileData.is_business_account || false,
    bio_links: bioClassification.bio_links_str,
    story_highlights: (profileData.story_highlights || []).join(', '),
    recent_posts_sample: profileData.recent_posts_sample || '',
    recent_posts_avg_likes: profileData.recent_posts_avg_likes || 0,
    is_verified: profileData.is_verified || false,
    // Bio classification
    has_product_page: bioClassification.has_product_page,
    has_booking: bioClassification.has_booking,
    enrichment_status: 'complete'
  }
}];
